'use client';

import { useCallback, useEffect, useState } from 'react';

export interface PlaylistRecord {
  id: number;
  name: string;
  description: string | null;
  cover_job_id: number | null;
  auto_generated: boolean;
  topic_keywords: string;
  color: string;
  created_at: string;
  item_count: number;
}

export interface JobRecord {
  id: number;
  url: string;
  status: string;
  progress: number;
  created_at: string;
  title?: string;
  author?: string;
  thumbnail?: string;
  duration?: number;
  video_path?: string;
}

const REST_API_BASE = 'http://localhost:8080/api/v1';

async function restRequest<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${REST_API_BASE}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(init?.headers ?? {}),
    },
  });
  if (!response.ok) {
    throw new Error(`REST ${path} failed with status ${response.status}`);
  }
  return response.json() as Promise<T>;
}

async function tauriInvoke<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  try {
    const { invoke } = await import('@tauri-apps/api/core');
    return await invoke<T>(command, args);
  } catch (error) {
    throw new Error(`Tauri invoke failed for ${command}: ${String(error)}`);
  }
}

export function usePlaylists() {
  const [playlists, setPlaylists] = useState<PlaylistRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedPlaylistId, setSelectedPlaylistId] = useState<number | null>(null);
  const [playlistItems, setPlaylistItems] = useState<JobRecord[]>([]);

  const fetchPlaylists = useCallback(async () => {
    setLoading(true);
    try {
      let data: PlaylistRecord[];
      try {
        data = await tauriInvoke<PlaylistRecord[]>('get_playlists');
      } catch {
        data = await restRequest<PlaylistRecord[]>('/playlists');
      }
      setPlaylists(data);
    } catch (error) {
      console.error('fetchPlaylists failed:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchPlaylistItems = useCallback(async (playlistId: number) => {
    try {
      let items: JobRecord[];
      try {
        items = await tauriInvoke<JobRecord[]>('get_playlist_items', { playlistId });
      } catch {
        items = await restRequest<JobRecord[]>(`/playlists/${playlistId}/items`);
      }
      setPlaylistItems(items);
    } catch (error) {
      console.error('fetchPlaylistItems failed:', error);
      setPlaylistItems([]);
    }
  }, []);

  const createPlaylist = useCallback(
    async (name: string, description?: string, color?: string) => {
      try {
        let id: number;
        try {
          id = await tauriInvoke<number>('create_playlist', { name, description, color });
        } catch {
          const response = await restRequest<{ id: number }>('/playlists', {
            method: 'POST',
            body: JSON.stringify({ name, description, color }),
          });
          id = response.id;
        }
        await fetchPlaylists();
        return id;
      } catch (error) {
        console.warn('createPlaylist falling back to local state:', error);
        const newPlaylist: PlaylistRecord = {
          id: Date.now(),
          name,
          description: description || null,
          cover_job_id: null,
          auto_generated: false,
          topic_keywords: '[]',
          color: color || '#8a5cff',
          created_at: new Date().toISOString(),
          item_count: 0,
        };
        setPlaylists((previous) => [newPlaylist, ...previous]);
        return newPlaylist.id;
      }
    },
    [fetchPlaylists],
  );

  const addToPlaylist = useCallback(
    async (playlistId: number, jobId: number) => {
      try {
        try {
          await tauriInvoke<void>('add_to_playlist', { playlistId, jobId });
        } catch {
          await restRequest<void>(`/playlists/${playlistId}/items`, {
            method: 'POST',
            body: JSON.stringify({ job_id: jobId }),
          });
        }
        if (selectedPlaylistId === playlistId) await fetchPlaylistItems(playlistId);
        await fetchPlaylists();
      } catch (error) {
        console.warn('addToPlaylist falling back to local count:', error);
        setPlaylists((previous) =>
          previous.map((playlist) =>
            playlist.id === playlistId
              ? { ...playlist, item_count: playlist.item_count + 1 }
              : playlist,
          ),
        );
      }
    },
    [fetchPlaylistItems, fetchPlaylists, selectedPlaylistId],
  );

  const removeFromPlaylist = useCallback(
    async (playlistId: number, jobId: number) => {
      try {
        try {
          await tauriInvoke<void>('remove_from_playlist', { playlistId, jobId });
        } catch {
          await restRequest<void>(`/playlists/${playlistId}/items/${jobId}`, { method: 'DELETE' });
        }
        if (selectedPlaylistId === playlistId) await fetchPlaylistItems(playlistId);
        await fetchPlaylists();
      } catch (error) {
        console.warn('removeFromPlaylist falling back to local count:', error);
        setPlaylists((previous) =>
          previous.map((playlist) =>
            playlist.id === playlistId
              ? { ...playlist, item_count: Math.max(0, playlist.item_count - 1) }
              : playlist,
          ),
        );
      }
    },
    [fetchPlaylistItems, fetchPlaylists, selectedPlaylistId],
  );

  const deletePlaylist = useCallback(
    async (playlistId: number) => {
      try {
        try {
          await tauriInvoke<void>('delete_playlist', { playlistId });
        } catch {
          await restRequest<void>(`/playlists/${playlistId}`, { method: 'DELETE' });
        }
        setPlaylists((previous) => previous.filter((playlist) => playlist.id !== playlistId));
        await fetchPlaylists();
      } catch (error) {
        console.warn('deletePlaylist falling back to local state:', error);
        setPlaylists((previous) => previous.filter((playlist) => playlist.id !== playlistId));
      }

      if (selectedPlaylistId === playlistId) {
        setSelectedPlaylistId(null);
        setPlaylistItems([]);
      }
    },
    [fetchPlaylists, selectedPlaylistId],
  );

  const selectPlaylist = useCallback(
    async (id: number | null) => {
      setSelectedPlaylistId(id);
      if (id === null) setPlaylistItems([]);
      else await fetchPlaylistItems(id);
    },
    [fetchPlaylistItems],
  );

  useEffect(() => {
    void fetchPlaylists();
  }, [fetchPlaylists]);

  return {
    playlists,
    loading,
    selectedPlaylistId,
    playlistItems,
    fetchPlaylists,
    createPlaylist,
    addToPlaylist,
    removeFromPlaylist,
    deletePlaylist,
    selectPlaylist,
  };
}

